import {memberName} from './teams.js?v=20261010-member-fixes';
import {restrictionActive} from './restrictions.js?v=20261010-member-fixes';
const previewResponses=new Map();
export const canRespond=(actor,canRead)=>Boolean(actor&&actor.user_metadata?.status==='approved'&&!restrictionActive(actor.user_metadata)&&canRead);
export function previewRecruitmentComments(id){return [...(previewResponses.get(id)?.values()||[])].map(item=>({...item.member,body:item.response==='attend'?'참석합니다.':'불참합니다.',created_at:item.created_at}));}
export function updateRecruitmentMember(member){for(const answers of previewResponses.values())for(const answer of answers.values())if(answer.member.id===member.id)answer.member={...answer.member,...member};}
export function recruitmentPanel(){return `<section class="recruitment-panel" aria-labelledby="recruitment-title"><div><h2 id="recruitment-title">참석 여부</h2><p id="recruitment-counts" role="status">참석 0명 · 불참 0명</p></div><div class="recruitment-buttons"><button class="secondary" type="button" data-response="attend" aria-pressed="false">참석</button><button class="secondary" type="button" data-response="decline" aria-pressed="false">불참</button></div><p class="form-note" id="recruitment-note">선택하면 본인 이름으로 댓글이 작성됩니다. 변경하면 기존 댓글이 수정됩니다.</p><p class="form-error" id="recruitment-error" role="alert"></p></section>`;}
export async function bindRecruitment(main,{post,actor,db,canRead,isCurrent,onAuth,onChanged}){
  const root=main.querySelector('.recruitment-panel');if(!root)return;
  const alive=()=>isCurrent()&&main.contains(root),eligible=canRespond(actor,canRead);
  let busy=false,state={attend:0,decline:0,mine:null};
  const localState=()=>{const answers=previewResponses.get(post.id)||new Map();return{attend:[...answers.values()].filter(a=>a.response==='attend').length,decline:[...answers.values()].filter(a=>a.response==='decline').length,mine:answers.get(actor?.id)?.response||null};};
  function draw(){root.querySelector('#recruitment-counts').textContent=`참석 ${state.attend}명 · 불참 ${state.decline}명`;for(const button of root.querySelectorAll('[data-response]')){button.setAttribute('aria-pressed',String(state.mine===button.dataset.response));button.disabled=busy||Boolean(actor&&!eligible);}if(!actor)root.querySelector('#recruitment-note').textContent='로그인 후 참석 여부를 남길 수 있습니다.';else if(!eligible)root.querySelector('#recruitment-note').textContent='승인된 회원만 참석 여부를 남길 수 있습니다.';}
  try{if(db){const{data,error}=await db.rpc('get_recruitment_response',{p_post:post.id});if(error)throw error;if(!alive())return;state=data;}else state=localState();draw();}catch{if(alive())root.querySelector('#recruitment-error').textContent='참석 현황을 불러오지 못했어요. 새로고침해 주세요.';return;}
  root.addEventListener('click',async event=>{const button=event.target.closest('[data-response]');if(!button||busy)return;if(!actor){onAuth();return;}if(!eligible)return;busy=true;draw();root.querySelector('#recruitment-error').textContent='';try{const response=button.dataset.response;if(db){const{data,error}=await db.rpc('set_recruitment_response',{p_post:post.id,p_response:response});if(error)throw error;if(!alive())return;state=data;}else{if(!previewResponses.has(post.id))previewResponses.set(post.id,new Map());const answers=previewResponses.get(post.id),previous=answers.get(actor.id);answers.set(actor.id,{response,member:{id:actor.id,...actor.user_metadata},created_at:previous?.created_at||new Date().toISOString()});state=localState();}if(alive())await onChanged();}catch{if(alive())root.querySelector('#recruitment-error').textContent='저장하지 못했어요. 로그인 상태와 게시판 권한을 확인해 주세요.';}finally{busy=false;if(alive())draw();}});
}
